/* global Office, Excel */
import { findLeftoverStagingSheets, deleteStagingSheets } from "@services/excelService";

/**
 * Handler untuk command ribbon "Bersihkan Staging".
 * Menghapus sheet sementara (__PS_*) yang tersisa jika add-in sebelumnya crash atau ditutup paksa.
 */
export async function cleanupStagingSheets(event: Office.AddinCommands.Event): Promise<void> {
  try {
    const leftover = await findLeftoverStagingSheets();
    if (leftover.length > 0) {
      await deleteStagingSheets(leftover);
      console.info(`[Print Studio] Berhasil membersihkan ${leftover.length} sheet staging sisa:`, leftover);
    } else {
      console.info("[Print Studio] Tidak ada sheet staging sisa yang ditemukan.");
    }
  } catch (error) {
    console.error("[Print Studio] Gagal membersihkan sheet staging:", error);
  } finally {
    // Wajib dipanggil untuk memberitahu Office bahwa command telah selesai dieksekusi
    event.completed();
  }
}

// Inisialisasi Office runtime dan daftarkan aksi command
Office.onReady(() => {
  Office.actions.associate("cleanupStagingSheets", cleanupStagingSheets);
});
